test('install mode inside a lease-holding run with GSTACK_UPGRADE_FORCE=1 upgrades anyway', () => {
  const f = fixture({ cloneAt: 'B' });
  // write ENV_INSTALLER, assume-unchanged, leaseDir as in the #3571 test
  const r = spawnSync('bash', ['-c', 'bash "$1" touch --pid $$ --root "$2" || exit 9; bash "$3" --for document-release', 'run', lease, f.root, BOOT], { env: { ...env, GSTACK_LEASE_DIR: leaseDir, GSTACK_UPGRADE_FORCE: '1' }, encoding: 'utf8', timeout: 120_000 });
  expect(r.stdout).toMatch(/^SELF_UPGRADE: done 1\.0\.1 -> 1\.0\.2$/m);
  expect(f.git(['rev-parse', 'HEAD'])).toBe(f.c);
});
